      "id": "tariff-escalation-timeline",
      "insight": "Emphasize the stepwise escalation pattern of US tariffs on Chinese goods and China's retaliatory tariffs, with key policy events annotated along the timeline"
    },
    {
      "id": "supply-chain-diversion",
      "insight": "Highlight the rising share of Vietnam and India in US imports over the trade war period, making the acceleration after 2018 visually prominent against China's declining share"
    },
    {
      "id": "bilateral-trade-volume",
      "insight": "Show the trajectory of total US-China bilateral trade volume across the period, emphasizing the dip during peak tariff periods and partial recovery phases"
    },
    {
      "id": "policy-event-markers",
      "insight": "Annotate critical policy milestones (Section 301 investigation, List 1-4 tariffs, Phase One deal, Biden-era reviews) on the timeline to contextualize inflection points in the data"
    }
  ]
}

